class LoggingBeanPostProcessor implements BeanPostProcessor {

    public Object postProcessBeforeInitialization(Object bean, String beanName) {
        System.out.println("PRZED inicjalizacja: " + beanName);
        return bean;
    }

    public Object postProcessAfterInitialization(Object bean, String beanName) {
        System.out.println("PO inicjalizacji: " + beanName);
        return bean;
    }
}
// Kolejnosc: BeanPostProcessor.before -> @PostConstruct -> BeanPostProcessor.after

class GreetingModifyingBeanFactoryPostProcessor implements BeanFactoryPostProcessor {

    public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) {
        BeanDefinition def = beanFactory.getBeanDefinition("configurableGreeter");
        def.getPropertyValues().add("greeting", "ZMODYFIKOWANE PRZEZ POST-PROCESSOR");
    }
}
